using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Runtime.Serialization.Json;
using System.Runtime.InteropServices;
using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;

namespace Onechanbara.Diagnostics {
public static class Core {
 public const string Revision="diagnostic-output-1";
 public static readonly string[] ModeIds={"direct-guest","direct-ui","native-fifo-ui"};
 public static string Hash(string p){SafePath(p);using(var f=File.OpenRead(p))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
 public static void SafePath(string p){if(String.IsNullOrWhiteSpace(p))throw new InvalidDataException("빈 경로입니다.");for(string a=Path.GetFullPath(p);!String.IsNullOrEmpty(a);a=Path.GetDirectoryName(a)){if((File.Exists(a)||Directory.Exists(a))&&(File.GetAttributes(a)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("연결 또는 재분석 경로는 사용할 수 없습니다: "+a);}}
 public static bool Within(string p,string root){return Path.GetFullPath(p).StartsWith(Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}
 public static void SafeTree(string p){SafePath(p);if(!Directory.Exists(p))return;foreach(var f in Directory.GetFiles(p))SafePath(f);foreach(var d in Directory.GetDirectories(p))SafeTree(d);}
 public static void NewDirectory(string p){SafePath(p);Directory.CreateDirectory(p);SafePath(p);}
 public static string Q(string s){if(s==null||s.IndexOfAny(new[]{'"','\r','\n','\0'})>=0)throw new InvalidDataException("지원하지 않는 경로 문자입니다.");int n=0;for(int i=s.Length-1;i>=0&&s[i]=='\\';i--)n++;return "\""+s+new string('\\',n)+"\"";}
 public static string TomlString(string s){return "\""+s.Replace("\\","\\\\").Replace("\"","\\\"").Replace("\r","\\r").Replace("\n","\\n")+"\"";}
 public static string Value(string text,string section,string key){string active="";string found=null;foreach(string raw in text.Replace("\r\n","\n").Split('\n')){string l=raw.Trim();if(l.StartsWith("[")&&l.EndsWith("]")){active=l.Substring(1,l.Length-2);continue;}if(active!=section)continue;var m=Regex.Match(l,"^"+Regex.Escape(key)+@"\s*=\s*(.*)$");if(!m.Success)continue;if(found!=null)throw new InvalidDataException("중복 설정: "+section+"."+key);found=StripComment(m.Groups[1].Value).Trim();}return found;}
 public static string StripComment(string s){bool quoted=false,literal=false,escape=false;for(int i=0;i<s.Length;i++){char c=s[i];if(escape){escape=false;continue;}if(quoted&&c=='\\'){escape=true;continue;}if(!literal&&c=='"')quoted=!quoted;else if(!quoted&&c=='\'')literal=!literal;else if(!quoted&&!literal&&c=='#')return s.Substring(0,i);}return s;}
 public static string StringValue(string text,string section,string key){var v=Value(text,section,key);if(v==null)return "";if(v.Length>=2&&v[0]=='\''&&v[v.Length-1]=='\'')return v.Substring(1,v.Length-2);if(v.Length<2||v[0]!='"'||v[v.Length-1]!='"')throw new InvalidDataException("문자열 설정 형식: "+key);var b=new StringBuilder();for(int i=1;i<v.Length-1;i++){char c=v[i];if(c=='\\'){if(++i>=v.Length-1)throw new InvalidDataException("경로 이스케이프: "+key);c=v[i];if(c!='\\'&&c!='"'&&c!='/')throw new InvalidDataException("지원하지 않는 경로 이스케이프: "+key);}b.Append(c);}return b.ToString();}
 public static string Set(string text,string section,string key,string value){Value(text,section,key);var lines=new List<string>(text.Replace("\r\n","\n").Split('\n'));int start=-1,end=lines.Count;for(int i=0;i<lines.Count;i++){string t=lines[i].Trim();if(t=="["+section+"]"){if(start>=0)throw new InvalidDataException("중복 설정 섹션: "+section);start=i;}else if(start>=0&&end==lines.Count&&t.StartsWith("[")&&t.EndsWith("]"))end=i;}if(start<0){lines.Add("["+section+"]");lines.Add(key+" = "+value);}else{bool replaced=false;for(int i=start+1;i<end;i++){if(Regex.IsMatch(lines[i],@"^\s*"+Regex.Escape(key)+@"\s*=")){lines[i]=key+" = "+value;replaced=true;break;}}if(!replaced)lines.Insert(end,key+" = "+value);}return String.Join("\r\n",lines);}
 public static Dictionary<string,object> ReadJson(string p){SafePath(p);using(var f=File.OpenRead(p)){var j=new DataContractJsonSerializer(typeof(Dictionary<string,object>),new DataContractJsonSerializerSettings{UseSimpleDictionaryFormat=true});return (Dictionary<string,object>)j.ReadObject(f);}}
 public static void WriteJson(string p,Dictionary<string,object> value){SafePath(p);using(var f=new FileStream(p,FileMode.CreateNew,FileAccess.Write,FileShare.Read)){var j=new DataContractJsonSerializer(typeof(Dictionary<string,object>),new DataContractJsonSerializerSettings{UseSimpleDictionaryFormat=true});j.WriteObject(f,value);}}
 public static string S(Dictionary<string,object> d,string k){object v;if(!d.TryGetValue(k,out v)||v==null)throw new InvalidDataException("기록 항목 누락: "+k);return Convert.ToString(v,CultureInfo.InvariantCulture);}
 public static string Optional(Dictionary<string,object> d,string k){object v;return d.TryGetValue(k,out v)&&v!=null?Convert.ToString(v,CultureInfo.InvariantCulture):"";}
 public static long TreeBytes(string path){SafePath(path);if(!Directory.Exists(path))return 0;long n=0;foreach(var f in Directory.GetFiles(path)){SafePath(f);n+=new FileInfo(f).Length;}foreach(var d in Directory.GetDirectories(path))n+=TreeBytes(d);return n;}
 public static void CopyTree(string source,string target,Action<string> progress){SafePath(source);SafePath(target);if(!Directory.Exists(source))return;if(Within(target,source)||Within(source,target)||String.Equals(Path.GetFullPath(source),Path.GetFullPath(target),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("원본과 복사 경로가 겹칩니다.");NewDirectory(target);foreach(var f in Directory.GetFiles(source)){string dst=Path.Combine(target,Path.GetFileName(f));CopyFile(f,dst);if(progress!=null)progress(Path.GetFileName(f));}foreach(var d in Directory.GetDirectories(source))CopyTree(d,Path.Combine(target,Path.GetFileName(d)),progress);}
 public static void CopyFile(string from,string to){SafePath(from);SafePath(to);using(var input=new FileStream(from,FileMode.Open,FileAccess.Read,FileShare.Read))using(var output=new FileStream(to,FileMode.CreateNew,FileAccess.Write,FileShare.None))input.CopyTo(output);if(Hash(from)!=Hash(to))throw new IOException("복사 검증 실패: "+from);}
 public static bool PrepareSnapshot(string source,string container,string metadataName,Dictionary<string,object> metadata){SafePath(container);if(Directory.Exists(container))return false;string stage=container+".preparing-"+Guid.NewGuid().ToString("N");try{NewDirectory(stage);string data=Path.Combine(stage,"data");CopyTree(source,data,null);NewDirectory(data);WriteJson(Path.Combine(stage,metadataName),metadata);Directory.Move(stage,container);return true;}catch{try{SafeTree(stage);if(Directory.Exists(stage))Directory.Delete(stage,true);}catch{}throw;}}
 public static void CheckNoXenia(){foreach(var p in Process.GetProcesses())using(p){string name;try{name=p.ProcessName;}catch{continue;}if(name.StartsWith("xenia",StringComparison.OrdinalIgnoreCase)||name.StartsWith("ocb17_",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("다른 제니아가 실행 중입니다. 게임을 종료한 뒤 비교 실행을 선택해 주세요.");}}
 public static string FindReceipt(string home){string found=FindReceiptFromAncestors(home);if(found.Length>0)return found;if(Environment.OSVersion.Platform!=PlatformID.Win32NT)return "";foreach(var desktop in new[]{Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.CommonDesktopDirectory)}){if(String.IsNullOrWhiteSpace(desktop)||!Directory.Exists(desktop))continue;try{SafePath(desktop);foreach(var link in Directory.GetFiles(desktop,"*.lnk")){string name=Path.GetFileName(link);if(name.IndexOf("오네찬바라",StringComparison.OrdinalIgnoreCase)<0&&name.IndexOf("Onechanbara",StringComparison.OrdinalIgnoreCase)<0)continue;foreach(var location in ExistingShortcutLocations(link)){if(String.IsNullOrWhiteSpace(location))continue;found=FindReceiptFromAncestors(location);if(found.Length>0)return found;}}}catch{}}return "";}
 public static string FindReceiptFromAncestors(string home){var candidates=new List<string>();for(string dir=Path.GetFullPath(home);dir!=null;dir=Path.GetDirectoryName(dir)){candidates.Add(Path.Combine(dir,"install.json"));candidates.Add(Path.Combine(dir,"config","OnechanbaraDirect","install.json"));candidates.Add(Path.Combine(dir,"OnechanbaraDirect","install.json"));}foreach(var p in candidates){if(!File.Exists(p))continue;try{var d=ReadJson(p);if(S(d,"Owner")=="Onechanbara.445007D2.DirectDXGI"&&S(d,"ContentMode")=="OriginalSharedContent")return p;}catch{}}return "";}
 public static string[] ExistingShortcutLocations(string link){object shell=null,shortcut=null;try{SafePath(link);if(!File.Exists(link)||!String.Equals(Path.GetExtension(link),".lnk",StringComparison.OrdinalIgnoreCase))return new string[0];var type=Type.GetTypeFromProgID("WScript.Shell");if(type==null)return new string[0];shell=Activator.CreateInstance(type);shortcut=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{link});string target=Convert.ToString(shortcut.GetType().InvokeMember("TargetPath",BindingFlags.GetProperty,null,shortcut,null));string working=Convert.ToString(shortcut.GetType().InvokeMember("WorkingDirectory",BindingFlags.GetProperty,null,shortcut,null));return new[]{File.Exists(target)?Path.GetDirectoryName(target):"",Directory.Exists(working)?working:""};}catch{return new string[0];}finally{if(shortcut!=null&&Marshal.IsComObject(shortcut))Marshal.FinalReleaseComObject(shortcut);if(shell!=null&&Marshal.IsComObject(shell))Marshal.FinalReleaseComObject(shell);}}
 public static string RuntimeHash(string manifest){var d=ReadJson(manifest);if(S(d,"display_revision")!=Revision)throw new InvalidDataException("진단 실행파일 버전이 일치하지 않습니다.");string hash=Optional(d,"exe_sha256");if(hash.Length==0)hash=Optional(d,"RuntimeSha256");if(!Regex.IsMatch(hash,@"\A[0-9a-fA-F]{64}\z"))throw new InvalidDataException("실행파일 해시 기록이 올바르지 않습니다.");return hash.ToLowerInvariant();}
 public static string RuntimeDirectory(string home){SafePath(home);string adjacent=Path.Combine(Path.GetFullPath(home),"runtime");SafePath(adjacent);if(Directory.Exists(adjacent))return adjacent;string parent=Path.GetDirectoryName(Path.GetFullPath(home));if(parent==null)throw new DirectoryNotFoundException("진단 실행파일의 runtime 폴더가 없습니다.");string fallback=Path.Combine(parent,"runtime");SafePath(fallback);return fallback;}
 public static string BuildConfig(string source,string storage,string cache,string content,string log,int mode){if(mode<0||mode>=ModeIds.Length)throw new ArgumentOutOfRangeException("mode");foreach(var p in new[]{storage,cache,content,log})SafePath(p);
  foreach(var kv in new[]{new[]{"GPU","gpu","\"vulkan\""},new[]{"GPU","render_target_path_vulkan","\"fsi\""},new[]{"GPU","occlusion_query","\"strict\""},new[]{"GPU","draw_resolution_scale_x","2"},new[]{"GPU","draw_resolution_scale_y","2"},new[]{"GPU","vsync","true"},new[]{"GPU","framerate_limit","0"},new[]{"General","time_scalar","1"}}){var actual=Value(source,kv[0],kv[1]);if(actual!=kv[2])throw new InvalidDataException("실사용 전용 설정의 기준값이 다릅니다: "+kv[1]+" = "+actual+". 원본은 변경하지 않았습니다.");}
  string text=source;foreach(var kv in new[]{new[]{"Storage","storage_root",storage},new[]{"Storage","cache_root",cache},new[]{"Storage","content_root",content},new[]{"Logging","log_file",log},new[]{"GPU.Debug","trace_gpu_prefix",Path.Combine(storage,"scratch","gpu")+Path.DirectorySeparatorChar}})text=Set(text,kv[0],kv[1],TomlString(kv[2]));
  foreach(var key in new[]{"vulkan_allow_present_mode_immediate","vulkan_allow_present_mode_mailbox","vulkan_allow_present_mode_fifo_relaxed"})text=Set(text,"Vulkan",key,"false");
  text=Set(text,"Vulkan","vulkan_direct_dxgi",mode==2?"false":"true");text=Set(text,"Vulkan","onechanbara_guest_output",mode==0?"true":"false");text=Set(text,"Display","onechanbara_diagnostics","true");
  // Existing private settings must not contain output paths beyond the new storage root.
  foreach(var pair in new[]{new[]{"GPU.Debug","dump_shaders"},new[]{"GPU.Debug","target_trace_file"},new[]{"GPU.Debug","trace_dump_path"},new[]{"CPU","trace_function_data_path"}}){if(StringValue(text,pair[0],pair[1])!="")throw new InvalidDataException("외부 분석 출력 경로가 지정되어 있습니다: "+pair[1]);}
  if(StringValue(text,"General","launch_module")!="")throw new InvalidDataException("추가 실행 모듈이 지정되어 있습니다.");
  return text;
 }
 public static string Args(string game,string config,string storage,string cache,string content,string log,int mode){return Q(game)+" --config="+Q(config)+" --storage_root="+Q(storage)+" --cache_root="+Q(cache)+" --content_root="+Q(content)+" --log_file="+Q(log)+" --gpu=vulkan --render_target_path_vulkan=fsi --vulkan_direct_dxgi="+(mode==2?"false":"true")+" --onechanbara_guest_output="+(mode==0?"true":"false")+" --onechanbara_diagnostics=true --vulkan_allow_present_mode_immediate=false --vulkan_allow_present_mode_mailbox=false --vulkan_allow_present_mode_fifo_relaxed=false";}
 public static string ZipRun(string run){string zip=run+".zip";SafePath(zip);using(var f=new FileStream(zip,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(var archive=new ZipArchive(f,ZipArchiveMode.Create)){foreach(var path in Directory.GetFiles(run)){SafePath(path);string ext=Path.GetExtension(path).ToLowerInvariant();if(ext!=".json"&&ext!=".toml"&&ext!=".log"&&ext!=".csv"&&ext!=".txt")continue;var e=archive.CreateEntry(Path.GetFileName(path),CompressionLevel.Optimal);using(var input=File.OpenRead(path))using(var output=e.Open())input.CopyTo(output);}}return zip;}
 public static string ZipRuns(string[] runs,string output){SafePath(output);using(var f=new FileStream(output,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(var archive=new ZipArchive(f,ZipArchiveMode.Create)){var index=new StringBuilder("Onechanbara v1.7 diagnostic-output-1\r\nThis archive contains completed runs from one launcher session.\r\n");foreach(var run in runs){SafePath(run);string prefix=Path.GetFileName(run);index.AppendLine(prefix);foreach(var path in Directory.GetFiles(run)){SafePath(path);string ext=Path.GetExtension(path).ToLowerInvariant();if(ext!=".json"&&ext!=".toml"&&ext!=".log"&&ext!=".csv"&&ext!=".txt")continue;var entry=archive.CreateEntry(prefix+"/"+Path.GetFileName(path),CompressionLevel.Optimal);using(var input=File.OpenRead(path))using(var result=entry.Open())input.CopyTo(result);}}var readme=archive.CreateEntry("comparison-runs.txt");using(var writer=new StreamWriter(readme.Open(),new UTF8Encoding(false)))writer.Write(index.ToString());}return output;}
}
}
